<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ $editing=$line!==null;$required='<span class="required-mark">*</span>';$phoneValue=preg_replace('/^\+55/','',(string)($line['phone_e164']??'')); ?>
<span class="status">ADM · WhatsApp</span><h1><?= $editing?'Editar linha':'Nova linha' ?></h1><p class="meta">Organize a unidade, os acessos e os identificadores fornecidos pela Meta.</p>
<?php if($error):?><div class="alert alert-danger"><?= $escape($error) ?></div><?php endif;?>
<form method="post" action="<?= $escape($basePath) ?>/whatsapp/lines<?= $editing?'/'.$escape($line['id']):'' ?>"><?= $csrfField ?><label>Nome da linha <?= $required ?><input name="name" required maxlength="120" value="<?= $escape($line['name']??'') ?>" placeholder="Ex.: WhatsApp Itapema"></label><label>Unidade <?= $required ?><select class="form-select" name="unit_id" required><option value="">Selecione</option><?php foreach($units as$unit):?><option value="<?= $escape($unit['id']) ?>" <?= (int)($line['unit_id']??0)===(int)$unit['id']?'selected':'' ?>><?= $escape($unit['name']) ?></option><?php endforeach;?></select></label><label>Número com DDD <?= $required ?><input name="phone" data-mask="phone" required maxlength="16" value="<?= $escape($phoneValue) ?>" placeholder="(48) 99999-9999"></label><h2>Conexão oficial</h2><p class="meta">Preencha após concluir o cadastro do número na Meta. Tokens e segredos permanecem somente no arquivo seguro da VPS.</p><div class="row"><div class="col-sm-6"><label>ID da conta WhatsApp Business<input name="waba_id" inputmode="numeric" maxlength="80" value="<?= $escape($line['waba_id']??'') ?>"></label></div><div class="col-sm-6"><label>ID do número na Meta<input name="phone_number_id" inputmode="numeric" maxlength="80" value="<?= $escape($line['phone_number_id']??'') ?>"></label></div></div><div class="alert <?= $credentialsReady?'alert-success':'alert-danger' ?>"><strong><?= $credentialsReady?'Credenciais da VPS configuradas.':'Credenciais da VPS ainda pendentes.' ?></strong><br>URL do webhook: <code><?= $escape($webhookUrl) ?></code></div><h2>Usuários autorizados</h2><p class="meta">Marque somente usuários que também possuem acesso à unidade selecionada.</p><div class="checks"><?php foreach($users as$person):?><label><input type="checkbox" name="users[]" value="<?= $escape($person['id']) ?>" <?= in_array((int)$person['id'],$selectedUsers,true)?'checked':'' ?>><span><strong><?= $escape($person['name']) ?></strong><br><small class="meta"><?= $escape($person['unit_names']?:'Sem unidade') ?></small></span></label><?php endforeach;?></div><div class="checks"><label><input type="checkbox" name="is_active" value="1" <?= !$editing||(int)$line['is_active']===1?'checked':'' ?>>Linha ativa</label></div><button type="submit">Salvar linha</button></form><p><a href="<?= $escape($basePath) ?>/whatsapp/lines">Cancelar</a></p>
